import { Button } from "@/registry/erbium/ui/button";
import { toast } from "@/registry/erbium/ui/toast";
export default function Demo() {
  return (
    <>
      <Button
        onClick={() =>
          toast.add({
            id: "toast-demo-saved",
            title: "Saved",
            description: "Your changes have been saved.",
          })
        }
      >
        Show toast
      </Button>
    </>
  );
}

import Demo from "../examples/toast-demo";

const Example = () => (
  <div className="w-full min-w-72 max-w-2xl p-4">
    <Demo />
  </div>
);

export default Example;
